842	function readBody(req: IncomingMessage): Promise<string> {
843	  return new Promise((resolve, reject) => {
844	    const chunks: Buffer[] = [];
845	    let size = 0;
846	    let tooLarge = false;
847	    let settled = false;
848	    // A declared Content-Length already tells us the request will exceed the
849	    // limit, but we must still consume the whole request before responding;
850	    // skip buffering from the start to bound memory use while draining.
851	    const declaredLength = Number(req.headers['content-length']);
852	    if (Number.isFinite(declaredLength) && declaredLength > MAX_BODY_BYTES) {
853	      tooLarge = true;
854	    }
855	    req.on('data', (chunk: unknown) => {
856	      if (settled) return;
857	      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
858	      if (tooLarge) return; // draining the remainder; nothing left to buffer
859	      size += buf.length;
860	      if (size > MAX_BODY_BYTES) {
861	        // Keep reading (and discarding) the rest of the request instead of
862	        // calling req.destroy(): destroying the socket resets the connection
863	        // while the client is still sending, so it would never receive the
864	        // 400 response (only a network failure). The full request is drained,
865	        // then the rejection below produces a complete, readable response.
866	        tooLarge = true;
867	        chunks.length = 0;
868	        return;
869	      }
870	      chunks.push(buf);
871	    });
872	    req.on('end', () => {
873	      if (settled) return;
874	      settled = true;
875	      if (tooLarge) {
876	        reject(new HttpError(400, `request body exceeds the allowed size of ${MAX_BODY_BYTES} bytes`));
877	        return;
878	      }
879	      resolve(Buffer.concat(chunks).toString('utf8'));
880	    });
881	    req.on('error', (error: Error) => {
882	      if (settled) return;
883	      settled = true;
884	      reject(new HttpError(400, `could not read request body: ${error.message}`));
885	    });
