948	  }
949	
950	  if (!['/', '/health', '/api/articles'].includes(route) && !itemMatch) {
951	    respond(res, 404, { error: 'not found' });
952	    return;
953	  }
954	
955	  if (route === '/') {
956	    if (req.method === 'GET') { respond(res, 200, PAGE, true); return; }
957	    methodNotAllowed(res, 'GET');
958	    return;
959	  }
960	  if (route === '/health') {
961	    if (req.method === 'GET') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
962	    methodNotAllowed(res, 'GET');
