987	          // 409 carries the currently saved article for side-by-side comparison.
988	          const conflict = new HttpError(409, 'a newer version of this article has been saved');
989	          (conflict as HttpError & { article?: Article }).article = current;
990	          throw conflict;
991	        }
992	        const updated: Article = {
993	          id: current.id,
994	          title: fields.title,
995	          summary: fields.summary,
996	          body: fields.body,
997	          status: current.status,
998	          createdAt: current.createdAt,
999	          version: current.version + 1,
1000	        };
1001	        records[index] = updated;
