      assert.equal(stored.body, `${v2.body}\n载入后补充一行`);
      assert.equal((await server.listArticles()).length, 1);
    } finally {
      ui.assertNoPageErrors(page);
      await browser.closePage(page);
      await server.stop();
    }
  } catch (error) {
    await server.stop();
    throw error;
  }
});

